UPDATE ALIADOS.RESTENDPOINTS SET "PATH"='ElectronicWarranty/Guarantee', "SEQUENCE"=1, VERB='GET', SUMMARY='Recupera una garantía electrónica por medio de número de garantía', DESCRIPTION=NULL, STATEMENTTYPE='SELECT', DATASOURCE=1, "STATEMENT"='SELECT ID "ID", Institution_identifier "Institution_identifier", Supplier_identifier "Supplier_identifier", Guarantee_identifier "Guarantee_identifier", Guarantee_name "Guarantee_name", Institucion_notice_number "Institucion_notice_number", Notice_number "Notice_number", Cuenta_cliente "Cuenta_cliente", Guarantee_charge_person_name "Guarantee_charge_person_name", Guarantee_charge_person_email "Guarantee_charge_person_email", Guarantee_telephone_number "Guarantee_telephone_number", Guarantee_postal_code "Guarantee_postal_code", Guarantee_address_line "Guarantee_address_line", Guarantee_number "Guarantee_number", Guarantee_sequencenumber "Guarantee_sequencenumber", Guarantee_type_code "Guarantee_type_code", Guarantee_payment_code "Guarantee_payment_code", Guarantee_amount "Guarantee_amount", Moneda "Moneda", Issue_date "Issue_date", Valid_period_date "Valid_period_date", Tipo_de_modification "Tipo_de_modification", Guarantee_contents "Guarantee_contents", Confirmation "Confirmation", Msg_err "Msg_err", UpdateUserCode "UpdateUserCode", UpdateDate "UpdateDate", SUPPLIER_NAME "Supplier_name", EX_METODO "Ex_Metodo", EX_CODIGO_PROCESO "Ex_Codigo_Proceso", EX_FECHA_PROCESO "Ex_Fecha_Proceso", EX_AMOUNT "Ex_Amount", EX_CONTENTS "Ex_Contents", EX_CUENTA_CLIENTE "Ex_Cuenta_Cliente" FROM ElectronicWarranty P WHERE Guarantee_number={code:VARCHAR2.14:Required} AND P.Guarantee_sequencenumber = (SELECT max(Guarantee_sequencenumber) FROM ElectronicWarranty M WHERE M.Guarantee_number = P.Guarantee_number)', ONERECORD=1, "SOURCE"='ElectronicWarranty', ALIAS='Guarantee', AUTHORIZATIONREQUIRED=1, ROLES=NULL, CONTROLLERNAME='ElectronicWarranty', APPNAME='ElectronicWarranty', TRACED=0, PRECONDITION=NULL, VALIDATIONS=NULL, RECORDSTATUS=1, COMPANYID=0